namespace docking.util;










public class AnimatedIcon : Icon {

	/** best guess at how many timer invocations may happen before paint gets called*/
	private static readonly int MAGIC_TIMER_CALLS_WITHOUT_PAINT_CALL = 5;

	private List<Icon> iconList;
	private int currentIconIndex = 0;
	private Component component;
	private int height;
	private int width;
	private int skipFrames;
	private int skipFrameCount = 0;
	private Timer timer;
	private int paintCounter = 0;

	public AnimatedIcon(List<Icon> icons, int frameDelay, int framesToSkip) {
		this.iconList = icons;
		this.skipFrames = framesToSkip;
		timer = new _Anon_Timer_1(frameDelay, new ActionListener());

		foreach (Icon icon in iconList) {
			width = Math.max(width, icon.getIconWidth());
			height = Math.max(height, icon.getIconHeight());
		}
	}

	/* @Override */
	public int getIconHeight() {
		return height;
	}

	/* @Override */
	public int getIconWidth() {
		return width;
	}

	private void restartAnimation() {
		timer.start();
		paintCounter = MAGIC_TIMER_CALLS_WITHOUT_PAINT_CALL;
	}

	/* @Override */
	public void paintIcon(Component c, Graphics g, int x, int y) {
		restartAnimation();
		iconList.get(currentIconIndex).paintIcon(c, g, x, y);
		component = c;
	}


	internal class _Anon_Timer_1 : Timer
	{
		public _Anon_Timer_1() : @base(frameDelay, new ActionListener() {}

			/* @Override */
			public void actionPerformed(ActionEvent e) {
				if (--paintCounter <= 0) {
					timer.stop();
					return;
				}

				if (skipFrameCount > 0) {
					skipFrameCount--;
					return;
				}
				if (++currentIconIndex >= iconList.size()) {
					currentIconIndex = 0;
					skipFrameCount = skipFrames;
				}
				if (component != null) {
					component.repaint();
				}
			}
		
	}

}
